# PATCH-007-Student-Style-Refactor.ps1
# CodeForge - readability/style cleanup only
#
# This patch does NOT change the database schema or reset data.
# It keeps the current features/logic and changes source presentation:
# - shorter comments
# - less over-explaining
# - easier-to-read page formatting
# - simpler naming/comments around implementation details
# - removal of patch/audit wording from source comments
#
# Run from D:\xampp\htdocs\codeforge

$ErrorActionPreference = 'Stop'

function Step([string]$msg) {
    Write-Host ''
    Write-Host "==> $msg" -ForegroundColor Cyan
}

$root = Split-Path -Parent $MyInvocation.MyCommand.Path
if (-not (Test-Path (Join-Path $root 'core\bootstrap.php'))) {
    $root = (Get-Location).Path
}
if (-not (Test-Path (Join-Path $root 'core\bootstrap.php'))) {
    throw 'Could not find CodeForge project root.'
}

Set-Location $root

$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$backup = Join-Path $root "patch-backups\PATCH-007-$stamp"
New-Item -ItemType Directory -Force -Path $backup | Out-Null

