$existed = @{}

Step 'Backing up files'
foreach ($rel in $files.Keys) {
    $src = Join-Path $root $rel
    $existed[$rel] = Test-Path $src

    if ($existed[$rel]) {
        $dest = Join-Path $backup $rel
        $parent = Split-Path -Parent $dest
        New-Item -ItemType Directory -Force -Path $parent | Out-Null
        Copy-Item $src $dest -Force
    }
}
Write-Host "[OK] $($files.Count) file(s) backed up" -ForegroundColor Green

function Rollback {
    Write-Host ''
    Write-Host 'Restoring PATCH-007 backup...' -ForegroundColor Yellow

    foreach ($rel in $files.Keys) {
        $target = Join-Path $root $rel
        $copy = Join-Path $backup $rel

        if ($existed[$rel]) {
            if (Test-Path $copy) {
                $parent = Split-Path -Parent $target
                New-Item -ItemType Directory -Force -Path $parent | Out-Null
                Copy-Item $copy $target -Force
            }
        } elseif (Test-Path $target) {
            Remove-Item $target -Force
        }
    }
}

try {
    Step 'Applying readability/style refactor'

    $utf8 = New-Object System.Text.UTF8Encoding($false)

    foreach ($rel in $files.Keys) {
        $data = ($files[$rel] -replace '\s', '')
        $bytes = [Convert]::FromBase64String($data)
        $content = [Text.Encoding]::UTF8.GetString($bytes)

        $target = Join-Path $root $rel
        $parent = Split-Path -Parent $target
        New-Item -ItemType Directory -Force -Path $parent | Out-Null
        [IO.File]::WriteAllText($target, $content, $utf8)
    }

    Write-Host '[OK] Source style changes written' -ForegroundColor Green

    $php = 'D:\xampp\php\php.exe'
    if (-not (Test-Path $php)) {
        $cmd = Get-Command php -ErrorAction SilentlyContinue
        if ($null -eq $cmd) {
            throw 'PHP executable not found.'
        }
        $php = $cmd.Source
    }

    Step 'Running full PHP syntax check'

    $failed = $false
    $oldPreference = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'

    Get-ChildItem -Path $root -Recurse -File -Filter '*.php' |
        Where-Object { $_.FullName -notlike '*\patch-backups\*' } |
        ForEach-Object {
            $result = & $php -l $_.FullName 2>&1
            if ($LASTEXITCODE -ne 0) {
                Write-Host "[FAIL] $($_.FullName)" -ForegroundColor Red
                $result | ForEach-Object { Write-Host $_ }
                $failed = $true
            }
        }

    $ErrorActionPreference = $oldPreference

    if ($failed) {
        Rollback
        throw 'PHP lint failed. PATCH-007 was rolled back.'
    }

    Write-Host '[OK] All PHP files passed syntax check' -ForegroundColor Green

    Step 'Running automated tests'

    $oldPreference = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    $testOutput = & $php (Join-Path $root 'tests\run.php') 2>&1
    $testCode = $LASTEXITCODE
    $ErrorActionPreference = $oldPreference

    $testOutput | ForEach-Object { Write-Host $_ }

    if ($testCode -ne 0 -or (($testOutput -join "`n") -notmatch '27 passed, 0 failed')) {
        Rollback
        throw 'Automated tests failed. PATCH-007 was rolled back.'
    }

    Step 'Done'
    Write-Host 'PATCH-007 APPLIED SUCCESSFULLY' -ForegroundColor Green
    Write-Host ''
    Write-Host 'The application behavior is unchanged.' -ForegroundColor White
    Write-Host 'Only source formatting/comments/readability were cleaned up.' -ForegroundColor White
    Write-Host ''
    Write-Host "Backup: $backup" -ForegroundColor DarkGray

} catch {
    Write-Host ''
    Write-Host $_.Exception.Message -ForegroundColor Red
    Write-Host "Backup: $backup" -ForegroundColor DarkGray
    exit 1
}
